<include file="Public:header"/><script type="text/javascript" src="{pigcms{$static_path}js/area_pca.js"></script>		<div class="mainbox">			<div id="nav" class="mainnav_title">				<ul>					<a href="{pigcms{:U('Platform/manage')}">平台分类列表</a>|					<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/add')}','添加分类',800,560,true,false,false,addbtn,'add',true);">添加分类</a>					<a href="{pigcms{:U('Platform/activity_list')}">平台活动列表</a>|					<a href=""  class="on">平台活动报名列表</a>|					<a href="{pigcms{:U('Platform/checkList')}">分类管理员审核列表</a>|				</ul>			</div>			<table class="search_table" width="100%">				<tr>					<td style="width:60%;">						<form action="{pigcms{:U('Platform/activity_join')}" method="get">							<input type="hidden" name="c" value="Platform"/>							<input type="hidden" name="a" value="activity_join"/>							<!-- 活动主题: 							<input type="text" name="title" value="{pigcms{$_GET.title}" style="height: 22px;width: 70px;"/> -->							订单号:							<input type="text" name="order_id" value="{pigcms{$_GET.order_id}" style="height: 22px;width: 70px;"/>							手机号:							<input type="text" name="phone" value="{pigcms{$_GET.phone}" style="height: 22px;width: 70px;"/>							姓名:							<input type="text" name="name" value="{pigcms{$_GET.name}" style="height: 22px;width: 70px;"/>							<input type="hidden" name="activity_id" value="{pigcms{$_GET.activity_id}" style="height: 22px;width: 70px;"/>							<input type="submit" value="查询" class="button"/>						</form>					</td>					<td>						<a href="{pigcms{:U('activity_export',$_GET)}"  class="button">导出活动报名列表</a>					</td>				</tr>			</table>							<div class="table-list">					<table width="100%" cellspacing="0">						<colgroup><col> <col> <col> <col><col><col><col><col><col width="240" align="center"> </colgroup>						<thead>							<tr>								<th>编号</th>								<th>活动主题</th>								<th>订单号</th>								<th>姓名</th>								<th>手机号</th>								<th>报名费用</th>								<th>会员等级</th>								<th>状态</th>								<!-- <th>报名自定义信息</th> -->								<th>添加时间</th>								<th>操作</th>							</tr>						</thead>						<tbody>							<if condition="is_array($list)">								<volist name="list" id="vo">									<tr>										<td>{pigcms{$vo.join_id}</td>										<td>{pigcms{$vo.title}</td>										<td>{pigcms{$vo.order_id}</td>										<td>{pigcms{$vo.name}</td>										<td>{pigcms{$vo.phone}</td>										<td>{pigcms{$vo.money}</td>										<td>											<if condition="!empty($vo['level'])">												{pigcms{$vo.lname}											<else/>												无											</if>										</td>										<td>											<if condition="$vo['status'] eq 0">													<font style="color:red;">报名失败</font>                                                <elseif condition="$vo['status'] eq 1"/>                                                    <font style="color:#6E8B3D;">报名成功</font>                                                <elseif condition="$vo['status'] eq 2"/>                                                    <font style="color:green;">已完成</font>                                                <elseif condition="$vo['status'] eq 3"/>													<font style="color:#EEB422;">待付款</font>                                                <elseif condition="$vo['status'] eq 4"/>                                                    已退款                                                <elseif condition="$vo['status'] eq 5"/>                                                已签到(已参加)                                                <elseif condition="$vo['status'] eq 6"/>                                                已取消                                            </if>										</td>										<!-- <td>											<if condition="$vo['content']">												{pigcms{$vo['content']}											<else/>												空											</if>											</td> -->										<td><if condition="$vo['add_time']">{pigcms{$vo.add_time|date='Y-m-d H:i:s',###}<else/>无</if></td>																				<td>										<a href="javascript:void(0);" onclick="window.top.artiframe('{pigcms{:U('Platform/activity_join_edit',array('id'=>$vo['join_id']))}','编辑报名信息',800,560,true,false,false,editbtn,'edit',true);">编辑</a>																				<!-- <a href="javascript:void(0);" class="delete_row" parameter="id={pigcms{$vo.id}" url="{pigcms{:U('Platform/del_cate')}">删除</a> -->										</td>									</tr>								</volist>								<tr><td class="textcenter pagebar" colspan="12">{pigcms{$pagebar}</td></tr>							<else/>								<tr><td class="textcenter red" colspan="12">列表为空！</td></tr>							</if>						</tbody>					</table>				</div>				</div><script>   var url = "{pigcms{$config.site_url}"    var export_url = "{pigcms{:U('Platform/export_info')}"</script><script type="text/javascript" src="{pigcms{$static_public}js/export.js"> </script><script>            var lockInfo = false;            function discoverSwitch(id, status) {            	console.log(id);                if (lockInfo) return;                lockInfo = true;                var url = '';                var close_category = "{pigcms{:U('Platform/close_cate')}";                var open_category = "{pigcms{:U('Platform/open_cate')}";                if (0 == status) {                    url = open_category;                } else if(1 == status) {                    url = close_category;                } else {                    return;                }                $.post(url,{'id': id},function(data){                    console.log(data)                    if (data && (data.status === 1 || data.status === '1')) {                        location.reload();                    } else {                        alert(data.info)                    }                },'json')                setTimeout(function(){                    lockInfo = false;                },1000);            }        </script><include file="Public:footer"/>